using System;using System.Drawing;using System.IO;using System.Windows.Forms;
namespace IDSketcher {
partial class Canvas {
 public void TestDrag(Point a,Point b){OnMouseDown(new MouseEventArgs(MouseButtons.Left,1,a.X,a.Y,0));OnMouseMove(new MouseEventArgs(MouseButtons.Left,0,b.X,b.Y,0));OnMouseUp(new MouseEventArgs(MouseButtons.Left,1,b.X,b.Y,0));}
 public void TestRotation(){SelectGuide("Ellipse");PointF old=guidePoints[0],c=Centre();SetEllipseRotation(90);PointF rotated=guidePoints[0];if(Math.Abs(rotated.X-c.X)>1||Math.Abs(rotated.Y-(c.Y+old.X-c.X))>1)throw new Exception("Ellipse rotation geometry");EditGuide=false;Tool="Pen";BrushSize=8;PressureMode="No pressure";PointF a=guidePoints[0],b=guidePoints[guidePoints.Length/4],mid=guidePoints[guidePoints.Length/8];TestDrag(Point.Round(a),Point.Round(b));if(Doc.Selected.Image.GetPixel((int)mid.X,(int)mid.Y).A==0)throw new Exception("Draw on rotated ellipse");EditGuide=true;PointF corner=RotateEllipse(GuideGrips()[0],EllipseRotation);TestDrag(Point.Round(corner),Point.Round(new PointF(corner.X+15,corner.Y+8)));if(StrokeSession.Distance(corner,RotateEllipse(GuideGrips()[0],EllipseRotation))<1)throw new Exception("Edit rotated ellipse");SelectGuide("Freehand");}
}
partial class Studio {
 public void TestNewFeatures(){
  SetDocument(new Document("A4",100),null);SelectTool("Pen");canvas.Zoom=1;canvas.Offset=PointF.Empty;canvas.PressureMode="No pressure";canvas.BrushSize=6;canvas.BrushOpacity=1;canvas.BrushFlow=1;canvas.Ink=Color.Red;
  int history=undo.Count;canvas.TestStraightDrag(new Point(40,40),new Point(200,100));if(undo.Count!=history+1||canvas.Doc.Selected.Image.GetPixel(120,70).A==0||canvas.Doc.Selected.Image.GetPixel(120,90).A!=0)throw new Exception("Shift drag straight with undo");Travel(undo,redo);if(canvas.Doc.Selected.Image.GetPixel(120,70).A!=0)throw new Exception("Undo Shift line");
  canvas.TestRotation();guideMode.SelectedItem="Ellipse";canvas.Focus();Message msg=new Message();ProcessCmdKey(ref msg,Keys.Tab);if(!canvas.EditGuide)throw new Exception("Tab edit guide");ProcessCmdKey(ref msg,Keys.Tab);if(canvas.EditGuide)throw new Exception("Tab draw guide");ProcessCmdKey(ref msg,Keys.Escape);if(canvas.Guide!="Freehand")throw new Exception("Escape freehand");
  foreach(string f in new[]{"RGB","HEX"}){mode.SelectedItem=f;colourEntry.Text=f=="RGB"?"255, 0, 128":"#FF0080";ApplyColourEntry();if(canvas.Ink.R!=255||canvas.Ink.G!=0||Math.Abs(canvas.Ink.B-128)>1)throw new Exception("Typed colour "+f);}Color previous=canvas.Ink;colourEntry.Text="not a colour";ApplyColourEntry();if(canvas.Ink!=previous)throw new Exception("Invalid colour must preserve selection");
  SetDocument(new Document("A4",100),null);canvas.Zoom=1;canvas.Offset=PointF.Empty;canvas.VectorWidth=6;canvas.VectorOpacity=1;canvas.Ink=Color.Blue;AddTypedLayer(true);
  vectorMode.SelectedItem="Line";canvas.TestDrag(new Point(40,40),new Point(200,40));
  vectorMode.SelectedItem="Ellipse";canvas.TestDrag(new Point(250,50),new Point(350,120));
  vectorMode.SelectedItem="Polyline";canvas.TestDrag(new Point(400,50),new Point(400,50));canvas.TestDrag(new Point(500,50),new Point(500,50));canvas.TestDrag(new Point(450,150),new Point(450,150));canvas.FinishVector();
  if(canvas.Doc.Selected.Vectors.Count!=3||canvas.Doc.Selected.Image.GetPixel(120,40).A!=0||canvas.Doc.Selected.Rendered().GetPixel(120,40).B!=255)throw new Exception("Retained vector geometry/rendering");
  vectorMode.SelectedItem="Select/edit";canvas.TestDrag(new Point(100,40),new Point(110,60));if(canvas.Doc.Selected.Vectors[0].Points[0]!=new PointF(50,60))throw new Exception("Move vector");canvas.TestDrag(new Point(50,60),new Point(60,80));if(canvas.Doc.Selected.Vectors[0].Points[0]!=new PointF(60,80))throw new Exception("Edit vector handle");Travel(undo,redo);if(canvas.Doc.Selected.Vectors[0].Points[0]!=new PointF(50,60))throw new Exception("Undo vector edit");Travel(redo,undo);
  canvas.TestDrag(new Point(135,70),new Point(135,70));canvas.Ink=Color.Green;canvas.VectorWidth=9;canvas.VectorOpacity=.6f;canvas.ApplyVectorStyle();if(canvas.Doc.Selected.Vectors[0].Colour!=Color.Green||canvas.Doc.Selected.Vectors[0].Width!=9)throw new Exception("Apply vector style");canvas.DeleteVector();if(canvas.Doc.Selected.Vectors.Count!=2)throw new Exception("Delete vector");Travel(undo,redo);if(canvas.Doc.Selected.Vectors.Count!=3)throw new Exception("Undo vector deletion");
  string path=Path.Combine(Path.GetTempPath(),Guid.NewGuid()+".idsk");try{canvas.Doc.Save(path);using(var loaded=Document.Load(path)){if(loaded.Selected.Vectors.Count!=3||loaded.Selected.Vectors[0].Points[0]!=new PointF(60,80))throw new Exception("Vector project persistence");using(var rendered=loaded.Flatten())if(rendered.GetPixel(300,50).B!=255)throw new Exception("Vector export");}}finally{if(File.Exists(path))File.Delete(path);}
  string legacy=Path.Combine(Path.GetTempPath(),Guid.NewGuid()+".idsk");try{using(var d=new Document("A4",100))using(var w=new BinaryWriter(File.Create(legacy))){w.Write("IDSKETCHER1");w.Write(d.Paper);w.Write(d.Dpi);w.Write(d.Width);w.Write(d.Height);w.Write(0);w.Write(1);w.Write("Legacy layer");w.Write(1f);w.Write(true);byte[] png=Document.Png(d.Selected.Image);w.Write(png.Length);w.Write(png);}using(var loaded=Document.Load(legacy))if(loaded.Selected.Name!="Legacy layer"||loaded.Selected.Vectors.Count!=0)throw new Exception("Legacy file compatibility");}finally{if(File.Exists(legacy))File.Delete(legacy);}
  Layer original=canvas.Doc.Selected;original.Opacity=.5f;original.Visible=false;DuplicateLayer();Layer copy=canvas.Doc.Selected;if(copy==original||copy.Vectors.Count!=3||copy.Visible||copy.Opacity!=.5f)throw new Exception("Duplicate layer metadata");copy.Vectors[0].Points[0]=new PointF(5,5);if(original.Vectors[0].Points[0]==new PointF(5,5))throw new Exception("Duplicate geometry must be independent");copy.Image.SetPixel(0,0,Color.Red);if(original.Image.GetPixel(0,0).A!=0)throw new Exception("Duplicate raster must be independent");
  FillLayer();if(copy.Vectors.Count!=1||!copy.Vectors[0].Filled)throw new Exception("Vector fill creates editable shape");Travel(undo,redo);if(copy.Vectors.Count!=3)throw new Exception("Undo fill restores vectors");dirty=false;
 }
}
}
